API Gateway / Ingress.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / Ingress container

Container_Boundary(api_gateway_ingress, "API Gateway / Ingress") {
    Component(Envoy_Proxy_Route_Manager, "Envoy Proxy Route Manager", "Envoy Proxy / Kubernetes Ingress Controller", "Handles traffic routing, TLS termination, and mTLS enforcement for incoming requests.")
    Component(Security_and_Authentication_Engine, "Security and Authentication Engine", "Envoy WAF and JWT Validation", "Validates JSON Web Tokens, applies Web Application Firewall rules, and enforces EU data residency constraints.")
    Component(Rate_Limiting_and_Policy_Module, "Rate Limiting and Policy Module", "Lua / WASM Rate-Limiting", "Enforces tiered rate-limiting and prioritization policies for patrons and staff.")
}

Rel(Envoy_Proxy_Route_Manager, Security_and_Authentication_Engine, "Passes incoming requests for JWT validation and WAF inspection", "Internal")
Rel(Security_and_Authentication_Engine, Rate_Limiting_and_Policy_Module, "Evaluates rate limits and priority rules", "Internal")

@enduml

Catalogue & Search Service Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(catalogue_search_service_container, "Catalogue & Search Service Container") {
    Component(grpc_api_handler, "gRPC API Handler", "Java/Spring", "Exposes endpoints, parses JWT claims for RBAC, and handles input sanitization.")
    Component(search_discovery_engine, "Search & Discovery Engine", "Elasticsearch client", "Handles DSL queries, facets, typo tolerance, and relevance.")
    Component(cataloguing_bulk_ingestion_worker, "Cataloguing & Bulk Ingestion Worker", "Java", "Processes write/update operations and schema validation.")
    Component(data_access_repository, "Data Access Repository", "Java/Spring Data", "Interfaces with storage engines.")
}

Rel(grpc_api_handler, search_discovery_engine, "In-process Java method calls", "")
Rel(grpc_api_handler, cataloguing_bulk_ingestion_worker, "In-process Java method calls", "")
Rel(cataloguing_bulk_ingestion_worker, data_access_repository, "Relational metadata persistence", "")

@enduml
